<?php
namespace Database\Seeders;
use App\Models\{AgentProfile,Amenity,Career,Currency,Post,Project,Property,PropertyCategory,Role,User};
use Illuminate\Database\Seeder; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class RecoveredCatalogSeeder extends Seeder {
 public function run():void{$path=database_path('data/recovered_catalog.json');if(!is_file($path)){return;}$data=json_decode(file_get_contents($path),true);if(!is_array($data))return;$currency=Currency::where('code','USD')->first();$category=PropertyCategory::first();$owner=User::firstOrCreate(['email'=>'recovered@example.com'],['name'=>'Recovered Catalog Owner','password'=>Str::random(40),'status'=>'active','email_verified_at'=>now()]);if($role=Role::where('slug','agent')->first())$owner->roles()->syncWithoutDetaching([$role->id]);
 foreach($data['agents']??[] as $i=>$item){$slug=$item['slug'];$u=User::firstOrCreate(['email'=>$slug.'@legacy.local'],['name'=>$item['title']?:Str::title($slug),'password'=>Str::random(40),'status'=>'active','email_verified_at'=>now()]);if($role=Role::where('slug','agent')->first())$u->roles()->syncWithoutDetaching([$role->id]);$profile=AgentProfile::updateOrCreate(['user_id'=>$u->id],['slug'=>$slug,'status'=>'active','verified_at'=>now()]);foreach($item['translations']??[] as $loc=>$tr)$profile->translations()->updateOrCreate(['locale'=>$loc],['display_name'=>$tr['title']??$item['title'],'seo_title'=>$tr['title']??$item['title'],'seo_description'=>$tr['meta_description']??null]);}
 foreach($data['projects']??[] as $i=>$item){$schema=$item['schema']??[];$p=Project::firstOrCreate(['reference_code'=>$item['overview']['Project ID']??('LEGACY-PRJ-'.str_pad((string)($i+1),4,'0',STR_PAD_LEFT))],['uuid'=>(string)Str::uuid(),'owner_id'=>$owner->id,'investor_name'=>$item['overview']['Investor']??null,'blocks_count'=>$this->number($item['overview']['Blocks']??null),'flats_count'=>$this->number($item['overview']['Flats']??null),'floors_count'=>$this->number($item['overview']['Floors']??null),'latitude'=>data_get($schema,'geo.latitude'),'longitude'=>data_get($schema,'geo.longitude'),'status'=>'published','published_at'=>now()->subDays(30-$i)]);foreach($item['translations']??['en'=>['title'=>$item['title'],'meta_description'=>$item['meta_description']??null]] as $loc=>$tr){$p->translations()->updateOrCreate(['locale'=>$loc],['name'=>$tr['title']??$item['title'],'slug'=>$loc==='en'?$item['slug']:$this->slug($tr['title']??$item['title'],$loc,$i),'description'=>$schema['description']??null,'seo_title'=>$tr['title']??$item['title'],'seo_description'=>$tr['meta_description']??null]);}foreach($item['amenities']??[] as $a){if($am=$this->amenity($a))$p->amenities()->syncWithoutDetaching([$am->id]);}foreach($item['nearby']??[] as $n)DB::table('project_nearby_places')->updateOrInsert(['project_id'=>$p->id,'type'=>$n['type']],['distance'=>$this->decimal($n['distance']??null),'distance_unit'=>'km','created_at'=>now(),'updated_at'=>now()]);}
 foreach($data['properties']??[] as $i=>$item){$schema=$item['schema']??[];$project=null;if($projectUrl=data_get($schema,'containedInPlace.url')){$slug=basename($projectUrl);$project=Project::whereHas('translations',fn($q)=>$q->where('locale','en')->where('slug',$slug))->first();}$price=data_get($schema,'price.price',0);$prop=Property::firstOrCreate(['reference_code'=>$item['overview']['Property ID']??('LEGACY-PROP-'.str_pad((string)($i+1),4,'0',STR_PAD_LEFT))],['uuid'=>(string)Str::uuid(),'owner_id'=>$owner->id,'project_id'=>$project?->id,'category_id'=>$category?->id,'currency_id'=>$currency->id,'purpose'=>'sale','status'=>'published','price'=>(float)$price,'bedrooms'=>$this->number($item['overview']['Bedrooms']??data_get($schema,'numberOfRooms')),'bathrooms'=>$this->number($item['overview']['Bathrooms']??data_get($schema,'numberOfBathroomsTotal')),'floors_count'=>$this->number($item['overview']['Floors']??null),'area'=>(float)(data_get($schema,'floorSize.value',0)?:0),'latitude'=>data_get($schema,'geo.latitude'),'longitude'=>data_get($schema,'geo.longitude'),'published_at'=>now()->subDays(62-$i)]);foreach($item['translations']??['en'=>['title'=>$item['title'],'meta_description'=>$item['meta_description']??null]] as $loc=>$tr){$prop->translations()->updateOrCreate(['locale'=>$loc],['name'=>$tr['title']??$item['title'],'slug'=>$loc==='en'?$item['slug']:$this->slug($tr['title']??$item['title'],$loc,$i),'description'=>$schema['description']??null,'address_text'=>data_get($schema,'address.streetAddress'),'seo_title'=>$tr['title']??$item['title'],'seo_description'=>$tr['meta_description']??null]);}foreach($item['amenities']??[] as $a){if($am=$this->amenity($a))$prop->amenities()->syncWithoutDetaching([$am->id]);}foreach($item['nearby']??[] as $n)DB::table('property_nearby_places')->updateOrInsert(['property_id'=>$prop->id,'type'=>$n['type']],['distance'=>$this->decimal($n['distance']??null),'distance_unit'=>'km','created_at'=>now(),'updated_at'=>now()]);foreach((array)($schema['image']??[]) as $j=>$url){$path=parse_url($url,PHP_URL_PATH);$path=ltrim((string)$path,'/');DB::table('property_media')->updateOrInsert(['property_id'=>$prop->id,'path'=>$path],['type'=>'image','disk'=>'legacy','sort_order'=>$j,'is_primary'=>$j===0,'created_at'=>now(),'updated_at'=>now()]);}}
 foreach($data['posts']??[] as $i=>$item){$post=Post::firstOrCreate(['id'=>$i+1],['author_id'=>$owner->id,'status'=>'published','published_at'=>now()->subDays(24-$i)]);foreach($item['translations']??[] as $loc=>$tr)$post->translations()->updateOrCreate(['locale'=>$loc],['title'=>$tr['title'],'slug'=>$loc==='en'?$item['slug']:$this->slug($tr['title'],$loc,$i),'excerpt'=>$tr['meta_description']??null,'content'=>$tr['meta_description']??null,'seo_title'=>$tr['title'],'seo_description'=>$tr['meta_description']??null]);}
 foreach($data['careers']??[] as $i=>$item){$career=Career::firstOrCreate(['id'=>$i+1],['status'=>'published']);foreach($item['translations']??[] as $loc=>$tr)$career->translations()->updateOrCreate(['locale'=>$loc],['title'=>$tr['title'],'slug'=>$loc==='en'?$item['slug']:$this->slug($tr['title'],$loc,$i),'summary'=>$tr['meta_description']??null,'description'=>$tr['meta_description']??null,'seo_title'=>$tr['title'],'seo_description'=>$tr['meta_description']??null]);}
 }
 private function amenity(string $name):?Amenity{$key=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));return Amenity::where('key',$key)->first();} private function number($v):?int{if($v===null||$v==='')return null;preg_match('/\d+/',(string)$v,$m);return isset($m[0])?(int)$m[0]:null;} private function decimal($v):?float{if(!$v)return null;return (float)preg_replace('/[^0-9.]/','',(string)$v);} private function slug(string $title,string $loc,int $i):string{$s=Str::slug($title);return ($s?:$loc.'-item').'-'.($i+1);}
}
